from fastapi import FastAPI, Query
from fastapi.responses import HTMLResponse, Response, JSONResponse
import json

app = FastAPI(title="競馬展開AI", version="1.0")

INDEX = '<!doctype html>\n<html lang="ja">\n<head>\n  <meta charset="utf-8" />\n  <meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover" />\n  <meta name="theme-color" content="#0f172a" />\n  <meta name="apple-mobile-web-app-capable" content="yes" />\n  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent" />\n  <meta name="apple-mobile-web-app-title" content="競馬展開AI" />\n  <link rel="manifest" href="./manifest.webmanifest" />\n  <link rel="apple-touch-icon" href="./assets/icon-192.png" />\n  <link rel="stylesheet" href="./styles.css" />\n  <title>競馬展開AI</title>\n</head>\n<body>\n  <div id="app"></div>\n  <script type="module" src="./app.js"></script>\n</body>\n</html>\n'
CSS = ':root {\n  --bg: #f5f6fa;\n  --card: #ffffff;\n  --text: #111827;\n  --muted: #6b7280;\n  --line: #e5e7eb;\n  --dark: #0f172a;\n  --soft: #f8fafc;\n  --accent: #111827;\n  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Text", "Hiragino Sans", "Noto Sans JP", sans-serif;\n  color: var(--text);\n  background: var(--bg);\n}\n* { box-sizing: border-box; }\nbody { margin: 0; min-height: 100vh; background: var(--bg); }\nbutton, input, select { font: inherit; }\nbutton { cursor: pointer; }\n.shell { max-width: 880px; margin: 0 auto; padding-bottom: calc(28px + env(safe-area-inset-bottom)); }\n.header { position: sticky; top: 0; z-index: 20; padding: calc(10px + env(safe-area-inset-top)) 16px 12px; background: rgba(15,23,42,.96); color: white; backdrop-filter: blur(14px); }\n.header-row { display:flex; align-items:center; justify-content:space-between; gap: 12px; }\n.header h1 { margin: 0; font-size: 20px; }\n.header small { color: #cbd5e1; }\n.icon-btn { border: 0; background: rgba(255,255,255,.12); color: white; border-radius: 12px; padding: 9px 11px; }\n.main { padding: 14px; display: grid; gap: 12px; }\n.card { background: var(--card); border: 1px solid var(--line); border-radius: 18px; padding: 15px; box-shadow: 0 8px 26px rgba(15,23,42,.04); }\n.card h2 { margin: 0 0 10px; font-size: 17px; }\n.card h3 { margin: 0 0 8px; font-size: 15px; }\n.muted { color: var(--muted); }\n.row { display:flex; gap: 10px; align-items:center; flex-wrap: wrap; }\n.row.between { justify-content: space-between; }\n.segment { display:grid; grid-template-columns:1fr 1fr; gap: 8px; }\n.segment button { border:1px solid var(--line); background:white; border-radius:14px; padding:12px; font-weight:700; }\n.segment button.active { background:var(--dark); color:white; border-color:var(--dark); }\n.date-input { width:100%; border:1px solid var(--line); border-radius:14px; padding:12px; background:white; }\n.venue-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:10px; }\n.venue-btn { text-align:left; border:1px solid var(--line); background:white; border-radius:15px; padding:13px; }\n.venue-btn strong { display:block; }\n.venue-btn span { font-size:12px; color:var(--muted); }\n.race-list { display:grid; gap:9px; }\n.race-btn { width:100%; text-align:left; border:1px solid var(--line); background:white; border-radius:15px; padding:12px 13px; display:flex; justify-content:space-between; gap:12px; align-items:center; }\n.race-btn.disabled { opacity:.45; }\n.pill { display:inline-flex; align-items:center; gap:5px; border-radius:999px; padding:5px 9px; background:#eef2f7; font-size:12px; font-weight:700; }\n.metrics { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }\n.metric { background:var(--soft); border-radius:14px; padding:10px; }\n.metric b { display:block; font-size:15px; }\n.metric span { font-size:11px; color:var(--muted); }\n.section-title { font-size:18px; font-weight:800; margin:5px 0 3px; }\n.table-wrap { overflow-x:auto; -webkit-overflow-scrolling:touch; border:1px solid var(--line); border-radius:14px; }\ntable { width:100%; border-collapse:collapse; min-width:760px; background:white; }\nth, td { padding:9px 8px; border-bottom:1px solid var(--line); text-align:center; font-size:12px; white-space:nowrap; }\nth { position:sticky; top:0; background:#f8fafc; z-index:1; font-size:11px; color:#475569; }\ntd.name { text-align:left; font-weight:700; }\n.score { font-weight:900; font-variant-numeric:tabular-nums; }\n.stage { padding:10px 0; border-bottom:1px solid var(--line); }\n.stage:last-child { border-bottom:0; }\n.stage b { display:block; font-size:12px; color:var(--muted); margin-bottom:4px; }\n.stage div { font-size:17px; font-weight:800; line-height:1.55; }\n.scenario-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:8px; }\n.scenario { background:var(--soft); border-radius:14px; padding:11px; min-height:104px; }\n.scenario .prob { font-size:22px; font-weight:900; }\n.scenario .horses { margin-top:8px; font-weight:800; }\n.marks { display:grid; gap:7px; }\n.mark-row { display:flex; align-items:center; gap:10px; background:var(--soft); border-radius:14px; padding:10px 12px; }\n.mark-symbol { width:28px; font-size:21px; font-weight:900; text-align:center; }\n.horse-card { border:1px solid var(--line); border-radius:14px; padding:11px; margin-top:9px; }\n.horse-card summary { cursor:pointer; font-weight:800; }\n.horse-detail { display:grid; gap:8px; padding-top:9px; }\n.statline { font-size:12px; color:#374151; }\n.recent { border-top:1px dashed var(--line); padding-top:8px; font-size:12px; }\n.back-btn { border:0; background:transparent; color:white; font-weight:700; padding:6px 0; }\n.empty { text-align:center; color:var(--muted); padding:28px 10px; }\n.notice { border-radius:14px; padding:11px 12px; background:#fff7ed; color:#9a3412; font-size:12px; }\n@media (max-width:620px) {\n  .main { padding:10px; }\n  .card { border-radius:16px; padding:13px; }\n  .scenario-grid { grid-template-columns:1fr; }\n  .metrics { grid-template-columns:1fr 1fr; }\n}\n'
JS = 'const CENTRAL = ["札幌","函館","福島","新潟","東京","中山","中京","京都","阪神","小倉"];\nconst LOCAL = ["帯広","門別","盛岡","水沢","浦和","船橋","大井","川崎","金沢","笠松","名古屋","園田","姫路","高知","佐賀"];\nconst API_DEFAULT = localStorage.getItem("keiba_api_base") || window.location.origin;\n\nconst state = {\n  circuit: "地方",\n  date: "2026-09-25",\n  races: [],\n  selectedTrack: null,\n  selectedRace: null,\n  loading: false,\n  error: null,\n};\n\nconst app = document.querySelector("#app");\nconst circled = n => n >= 1 && n <= 20 ? String.fromCodePoint(0x245f + n) : String(n);\nconst pct = v => `${Math.round(v * 100)}%`;\nconst fmtMoney = n => new Intl.NumberFormat("ja-JP").format(n || 0);\nconst seasonOf = iso => {\n  const m = Number(String(iso).split("-")[1]);\n  if (m >= 3 && m <= 5) return "春";\n  if (m >= 6 && m <= 8) return "夏";\n  if (m >= 9 && m <= 11) return "秋";\n  return "冬";\n};\n\nfunction styleRates(horse) {\n  const counts = {front:0, stalk:0, mid:0, close:0};\n  let total = 0;\n  for (const r of horse.recentRaces || []) {\n    const first = r.cornerPositions?.[0];\n    if (!Number.isFinite(first)) continue;\n    total++;\n    if (first === 1) counts.front++;\n    else if (first <= 4) counts.stalk++;\n    else if (first <= 7) counts.mid++;\n    else counts.close++;\n  }\n  const d = total || 1;\n  return {front:counts.front/d, stalk:counts.stalk/d, mid:counts.mid/d, close:counts.close/d};\n}\nfunction fadeRate(horse) {\n  const eligible = (horse.recentRaces || []).filter(r => (r.cornerPositions?.[0] ?? 99) <= 4);\n  if (!eligible.length) return 0;\n  const faded = eligible.filter(r => {\n    const first = r.cornerPositions?.[0];\n    const last = r.cornerPositions?.at(-1);\n    return Number.isFinite(first) && Number.isFinite(last) && (last >= first + 2 || r.finish >= first + 3);\n  }).length;\n  return faded / eligible.length;\n}\nfunction styleScore(horse) {\n  const r = styleRates(horse);\n  return r.front*1 + r.stalk*2 + r.mid*3 + r.close*4;\n}\nfunction expectedStyle(score) {\n  if (score < 1.6) return "逃げ";\n  if (score < 2.35) return "先行";\n  if (score < 3.1) return "好位〜差し";\n  return "後方";\n}\nfunction occupancy(horses) {\n  const early = [], moved = [];\n  for (const h of horses) {\n    const last = h.recentRaces?.[0];\n    if (!last?.cornerPositions?.length) continue;\n    const pos = last.cornerPositions;\n    if (!pos.some(x => x <= 3)) continue;\n    if (pos[0] <= 3) early.push(h.horseNumber); else moved.push(h.horseNumber);\n  }\n  const nums = [...early, ...moved].sort((a,b)=>a-b);\n  return { rate: horses.length ? nums.length/horses.length : 0, nums, early, moved };\n}\nfunction styleMap(horses) {\n  return horses.map(h => {\n    const r = styleRates(h), score = styleScore(h);\n    return {horse:h, score, ...r, fade:fadeRate(h), expected:expectedStyle(score)};\n  }).sort((a,b)=> a.score-b.score || a.horse.horseNumber-b.horse.horseNumber);\n}\nfunction buildStages(rows) {\n  const nums = rows.map(r=>r.horse.horseNumber);\n  const n = nums.length;\n  const fEnd = Math.max(1, Math.ceil(n*.25));\n  const sEnd = Math.max(fEnd+1, Math.ceil(n*.55));\n  const front = nums.slice(0,fEnd), stalk = nums.slice(fEnd,sEnd), back = nums.slice(sEnd);\n  const join = arr => arr.map(circled).join(" ") || "—";\n  const base = `${join(front)} → ${join(stalk)} → ${join(back)}`;\n  const movers = [...back.slice(0,2)].reverse();\n  const late = `${join(front)} → ${join(stalk)} → ${join(movers.length?movers:back)}`;\n  return [\n    ["スタート〜100m", base], ["最初のコーナー", base], ["向正面", late], ["3〜4角", late], ["直線", late]\n  ];\n}\nfunction scenarios(rows, occ) {\n  const front = rows.filter(r=>r.score<2.35);\n  const highFade = front.filter(r=>r.fade>=.5).length;\n  let a=40,c=20;\n  if (front.length<=2){a+=10;c-=5}\n  if (highFade>=2){c+=10;a-=5}\n  if (occ.rate>=.6){c+=5;a-=5}\n  a=Math.max(15,Math.min(60,a)); c=Math.max(10,Math.min(45,c));\n  const b=100-a-c;\n  return [\n    {code:"A", title:"前残り", prob:a, horses:rows.filter(r=>r.score<2.8).slice(0,4).map(r=>r.horse.horseNumber)},\n    {code:"B", title:"平均", prob:b, horses:rows.slice(0,5).map(r=>r.horse.horseNumber)},\n    {code:"C", title:"前崩れ・差し届く", prob:c, horses:[...rows].sort((x,y)=>y.score-x.score).slice(0,4).map(r=>r.horse.horseNumber)}\n  ];\n}\nfunction placeRate(s){return !s?.starts ? 0 : ((s.wins||0)+(s.seconds||0)+(s.thirds||0))/s.starts}\nfunction marks(race, rows) {\n  const maxPrize = Math.max(...race.horses.map(h=>h.prizeMoneyAtRace||0),1);\n  const scored = race.horses.map(h=>{\n    const recent=(h.recentRaces||[]).slice(0,3);\n    const rs=recent.length?recent.reduce((s,r)=>s+Math.max(0,12-r.finish),0)/recent.length:0;\n    const ps=(h.prizeMoneyAtRace||0)/maxPrize*3;\n    const js=placeRate(h.jockeyStats)*2, ts=placeRate(h.trainerStats)*1.5;\n    const sustain=(1-fadeRate(h))*2;\n    const fit=Math.max(0,2-Math.abs(styleScore(h)-2.2));\n    return {h, score:rs+ps+js+ts+sustain+fit};\n  }).sort((a,b)=>b.score-a.score);\n  const syms=["◎","○","▲","☆","△","注"];\n  return syms.map((s,i)=> scored[i] ? [s,scored[i].h] : null).filter(Boolean);\n}\nfunction predict(race){\n  const occ=occupancy(race.horses), rows=styleMap(race.horses);\n  return {occ,rows,stages:buildStages(rows),scenarios:scenarios(rows,occ),marks:marks(race,rows)};\n}\n\nasync function loadRaces() {\n  state.loading=true; state.error=null; render();\n  try {\n    let races=[];\n    if (API_DEFAULT) {\n      const url=`${API_DEFAULT.replace(/\\/$/,"")}/api/v1/races?date=${encodeURIComponent(state.date)}`;\n      const res=await fetch(url,{cache:"no-store"});\n      if (!res.ok) throw new Error(`API ${res.status}`);\n      const body=await res.json(); races=Array.isArray(body)?body:(body.races||[]);\n    } else {\n      const res=await fetch("./data/sample_races.json",{cache:"no-store"});\n      if (!res.ok) throw new Error("sample load failed");\n      races=await res.json();\n    }\n    state.races=races.filter(r=>r.date===state.date);\n    state.selectedTrack=null; state.selectedRace=null;\n  } catch (e) { state.error=String(e.message||e); state.races=[]; }\n  finally { state.loading=false; render(); }\n}\n\nfunction header(title, back=false) {\n  return `<header class="header"><div class="header-row">${back?\'<button class="back-btn" data-action="back">‹ 戻る</button>\':\'\'}<div><h1>${title}</h1><small>競馬展開AI</small></div><button class="icon-btn" data-action="reload">↻</button></div></header>`;\n}\nfunction renderHome(){\n  const venues=(state.circuit==="中央"?CENTRAL:LOCAL).filter(t=>state.races.some(r=>r.circuit===state.circuit&&r.track===t));\n  return `<div class="shell">${header("レース選択")}\n    <main class="main">\n      <section class="card"><h2>日付</h2><input class="date-input" id="date" type="date" value="${state.date}"></section>\n      <section class="card"><h2>区分</h2><div class="segment"><button data-circuit="中央" class="${state.circuit===\'中央\'?\'active\':\'\'}">中央</button><button data-circuit="地方" class="${state.circuit===\'地方\'?\'active\':\'\'}">地方</button></div></section>\n      <section class="card"><div class="row between"><h2>開催場</h2><span class="pill">${state.races.filter(r=>r.circuit===state.circuit).length}レース取得</span></div>\n      ${state.loading?\'<div class="empty">読込中…</div>\':state.error?`<div class="notice">${state.error}</div>`:venues.length?`<div class="venue-grid">${venues.map(t=>{const n=state.races.filter(r=>r.circuit===state.circuit&&r.track===t).length;return `<button class="venue-btn" data-track="${t}"><strong>${t}</strong><span>${n}レース</span></button>`}).join(\'\')}</div>`:\'<div class="empty">この日の取得データはありません</div>\'}</section>\n      <section class="card"><div class="muted" style="font-size:12px">季節・天候・馬場、年齢/性別/斤量、騎手/調教師成績、レース時点の獲得賞金、直近走を保持します。</div></section>\n    </main></div>`;\n}\nfunction renderVenue(){\n  const races=state.races.filter(r=>r.circuit===state.circuit&&r.track===state.selectedTrack).sort((a,b)=>a.raceNumber-b.raceNumber);\n  const byNo=Object.fromEntries(races.map(r=>[r.raceNumber,r]));\n  return `<div class="shell">${header(state.selectedTrack,true)}<main class="main"><section class="card"><div class="row between"><div><h2>${state.date}</h2><div class="muted">${state.circuit}・${state.selectedTrack}</div></div><span class="pill">${seasonOf(state.date)}</span></div></section><section class="card"><h2>1R〜12R</h2><div class="race-list">${Array.from({length:12},(_,i)=>i+1).map(no=>{const r=byNo[no]; return r?`<button class="race-btn" data-race="${r.id}"><div><strong>${no}R ${r.title}</strong><div class="muted">${r.distance}m・${r.condition}・${r.weather||\'不明\'}・${r.startTime}</div></div><span>›</span></button>`:`<button class="race-btn disabled" disabled><div><strong>${no}R</strong><div class="muted">未取得</div></div></button>`}).join(\'\')}</div></section></main></div>`;\n}\nfunction renderRace(){\n  const r=state.selectedRace, p=predict(r);\n  const early=p.occ.early.map(circled).join(\' \'), moved=p.occ.moved.map(circled).join(\' \');\n  return `<div class="shell">${header(`${r.track}${r.raceNumber}R`,true)}<main class="main">\n    <section class="card"><div class="row between"><div><h2>${r.title}</h2><div class="muted">${r.date} ${r.startTime}</div></div><span class="pill">${r.circuit}</span></div><div class="metrics" style="margin-top:10px"><div class="metric"><b>${r.distance}m</b><span>距離</span></div><div class="metric"><b>${r.condition}</b><span>馬場</span></div><div class="metric"><b>${r.weather||\'不明\'}</b><span>天候</span></div><div class="metric"><b>${seasonOf(r.date)}</b><span>季節</span></div><div class="metric"><b>${r.horses.length}頭</b><span>頭数</span></div></div></section>\n    <section class="card"><div class="section-title">1\u3000先行馬占有率</div><div style="font-size:32px;font-weight:900">${pct(p.occ.rate)}</div><div class="muted">対象：${p.occ.nums.map(circled).join(\' \')||\'—\'}</div><div class="muted" style="font-size:12px;margin-top:4px">最初から前：${early||\'—\'}\u3000途中進出：${moved||\'—\'}</div></section>\n    <section class="card"><div class="section-title">2\u3000脚質マップ</div><div class="muted" style="font-size:12px;margin-bottom:8px">脚質点の昇順。低いほど前、高いほど後方型。</div><div class="table-wrap"><table><thead><tr><th>順位</th><th>馬</th><th>脚質点</th><th>逃</th><th>先</th><th>差</th><th>追</th><th>下がり</th><th>今回想定</th></tr></thead><tbody>${p.rows.map((x,i)=>`<tr><td>${i+1}</td><td class="name">${circled(x.horse.horseNumber)} ${x.horse.name}</td><td class="score">${x.score.toFixed(2)}</td><td>${pct(x.front)}</td><td>${pct(x.stalk)}</td><td>${pct(x.mid)}</td><td>${pct(x.close)}</td><td>${pct(x.fade)}</td><td>${x.expected}</td></tr>`).join(\'\')}</tbody></table></div></section>\n    <section class="card"><div class="section-title">3\u3000隊列</div>${p.stages.map(([n,v])=>`<div class="stage"><b>${n}</b><div>${v}</div></div>`).join(\'\')}</section>\n    <section class="card"><div class="section-title">4\u3000ABC</div><div class="scenario-grid">${p.scenarios.map(s=>`<div class="scenario"><b>${s.code} ${s.title}</b><div class="prob">${s.prob}%</div><div class="horses">${s.horses.map(circled).join(\' \')}</div></div>`).join(\'\')}</div></section>\n    <section class="card"><div class="section-title">5\u3000印</div><div class="marks">${p.marks.map(([s,h])=>`<div class="mark-row"><div class="mark-symbol">${s}</div><div><strong>${circled(h.horseNumber)} ${h.name}</strong><div class="muted" style="font-size:12px">${h.sex}${h.age}・${h.carriedWeight}kg・${h.jockey}</div></div></div>`).join(\'\')}</div></section>\n    <section class="card"><h2>出走馬データ</h2>${r.horses.sort((a,b)=>a.horseNumber-b.horseNumber).map(h=>`<details class="horse-card"><summary>${circled(h.horseNumber)} ${h.name}\u3000${h.sex}${h.age} ${h.carriedWeight}kg</summary><div class="horse-detail"><div class="statline">騎手：${h.jockey}（${h.jockeyStats?.starts||0}戦 ${h.jockeyStats?.wins||0}勝 / 複勝率${pct(placeRate(h.jockeyStats))}）</div><div class="statline">調教師：${h.trainer}（${h.trainerStats?.starts||0}戦 ${h.trainerStats?.wins||0}勝 / 複勝率${pct(placeRate(h.trainerStats))}）</div><div class="statline">このレース時点の獲得賞金：${fmtMoney(h.prizeMoneyAtRace)}円</div>${(h.recentRaces||[]).map(rr=>`<div class="recent"><b>${rr.date} ${rr.track} ${rr.distance}m</b>\u3000${rr.finish}着 / ${rr.timeSeconds.toFixed(1)}秒<br><span class="muted">${rr.condition}・${rr.weather||\'不明\'}・${seasonOf(rr.date)}\u3000通過 ${rr.cornerPositions?.join(\'-\')||\'—\'}</span></div>`).join(\'\')}</div></details>`).join(\'\')}</section>\n  </main></div>`;\n}\nfunction render(){\n  if (state.selectedRace) app.innerHTML=renderRace();\n  else if (state.selectedTrack) app.innerHTML=renderVenue();\n  else app.innerHTML=renderHome();\n  bind();\n}\nfunction bind(){\n  document.querySelectorAll(\'[data-circuit]\').forEach(b=>b.onclick=()=>{state.circuit=b.dataset.circuit;state.selectedTrack=null;state.selectedRace=null;render()});\n  document.querySelector(\'#date\')?.addEventListener(\'change\',e=>{state.date=e.target.value;loadRaces()});\n  document.querySelectorAll(\'[data-track]\').forEach(b=>b.onclick=()=>{state.selectedTrack=b.dataset.track;render()});\n  document.querySelectorAll(\'[data-race]\').forEach(b=>b.onclick=()=>{state.selectedRace=state.races.find(r=>r.id===b.dataset.race);render()});\n  document.querySelectorAll(\'[data-action="back"]\').forEach(b=>b.onclick=()=>{if(state.selectedRace)state.selectedRace=null;else state.selectedTrack=null;render()});\n  document.querySelectorAll(\'[data-action="reload"]\').forEach(b=>b.onclick=()=>loadRaces());\n}\nif (\'serviceWorker\' in navigator) window.addEventListener(\'load\',()=>navigator.serviceWorker.register(\'./sw.js\').catch(()=>{}));\nloadRaces();\n'
MANIFEST = '{\n  "name": "競馬展開AI",\n  "short_name": "競馬展開AI",\n  "description": "中央・地方競馬の脚質マップ、隊列、ABC展開、印を確認するPWA",\n  "start_url": "./",\n  "scope": "./",\n  "display": "standalone",\n  "background_color": "#f6f7fb",\n  "theme_color": "#0f172a",\n  "lang": "ja",\n  "icons": [\n    {"src": "./assets/icon-192.png", "sizes": "192x192", "type": "image/png"},\n    {"src": "./assets/icon-512.png", "sizes": "512x512", "type": "image/png"}\n  ]\n}\n'
