@app.get("/health")
def health():
    return {"status":"ok","mode":"iphone-simple"}

@app.get("/api/v1/races")
def races(date: str = Query(...)):
    return [r for r in SAMPLES if r.get("date") == date]

@app.get("/", response_class=HTMLResponse)
def home():
    return HTMLResponse(INDEX)

@app.get("/styles.css")
def styles():
    return Response(CSS, media_type="text/css")

@app.get("/app.js")
def appjs():
    return Response(JS, media_type="application/javascript")

@app.get("/manifest.webmanifest")
def manifest():
    return Response(MANIFEST, media_type="application/manifest+json")

@app.get("/sw.js")
def service_worker():
    return Response(SW, media_type="application/javascript", headers={"Service-Worker-Allowed":"/"})
